def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def times(A, x):
    return [sum(A[i][j] * x[j] for j in range(len(x))) for i in range(len(A))]

def check(A, v):
    if all(x == 0 for x in v):
        print("  the zero vector is never an eigenvector")
        return
    Av = times(A, v)
    i = [j for j in range(len(v)) if v[j] != 0][0]
    lam = Av[i] / v[i]
    if all(Av[j] == lam * v[j] for j in range(len(v))):
        print(f"  A v = {vec(Av)}, eigenvalue {lam}")
    else:
        print(f"  A v = {vec(Av)}, not an eigenvector")

k = int(input())
for t in range(k):
    n = int(input())
    A = [[Fraction(w) for w in input().split()] for i in range(n)]
    v = [Fraction(w) for w in input().split()]
    print(f"A = {show(A)}, v = {vec(v)}")
    check(A, v)

