from fractions import Fraction

def rref(M, cols):
    R = [[Fraction(x) for x in row] for row in M]
    pivots = []
    for c in range(cols):
        r = len(pivots)
        p = r
        while p < len(R) and R[p][c] == 0:
            p = p + 1
        if p == len(R):
            continue
        R[r], R[p] = R[p], R[r]
        k = R[r][c]
        R[r] = [x / k for x in R[r]]
        for i in range(len(R)):
            k = R[i][c]
            if i != r and k != 0:
                R[i] = [R[i][j] - k * R[r][j] for j in range(len(R[i]))]
        pivots.append(c)
    return R, pivots

def show(M):
    return "  ".join("[" + ", ".join(str(x) for x in row) + "]" for row in M)

def vec(v):
    return "(" + ", ".join(str(x) for x in v) + ")"

def special(R, pivots, n):
    result = []
    for f in [j for j in range(n) if j not in pivots]:
        s = [Fraction(0)] * n
        s[f] = Fraction(1)
        for i in range(len(pivots)):
            s[pivots[i]] = -R[i][f]
        result.append(s)
    return result

def eigenspace(A, lam):
    n = len(A)
    M = [[A[i][j] - (lam if i == j else 0) for j in range(n)] for i in range(n)]
    R, pivots = rref(M, n)
    vs = special(R, pivots, n)
    if not vs:
        print(f"  lambda = {lam}: not an eigenvalue")
    else:
        print(f"  lambda = {lam}: dimension {len(vs)}, v = {', '.join(vec(v) for v in vs)}")

k = int(input())
for t in range(k):
    n, m = [int(w) for w in input().split()]
    A = [[Fraction(w) for w in input().split()] for i in range(n)]
    lams = [Fraction(w) for w in input().split()]
    print(f"A = {show(A)}")
    for lam in lams:
        eigenspace(A, lam)
